/**
 * Authentication Service
 * 
 * Handles all authentication-related API calls
 */
import api from './api';

/**
 * Login with email and password
 * @param {string} email - User email
 * @param {string} password - User password
 * @param {boolean} rememberMe - Whether to remember the user
 * @returns {Promise} - The response promise
 */
export const login = async (email, password, rememberMe = false) => {
  const response = await api.post('/auth/login', { email, password, rememberMe });
  
  // Store tokens in localStorage
  if (response.data.accessToken) {
    localStorage.setItem('accessToken', response.data.accessToken);
    
    if (response.data.refreshToken) {
      localStorage.setItem('refreshToken', response.data.refreshToken);
    }
  }
  
  return response.data;
};

/**
 * Register a new user
 * @param {Object} userData - User registration data
 * @returns {Promise} - The response promise
 */
export const register = async (userData) => {
  try {
    console.log('Sending registration data to API:', userData);
    const response = await api.post('/auth/register', userData);
    console.log('Registration API response:', response.data);
    
    // Store tokens in localStorage if they're returned
    if (response.data.accessToken) {
      localStorage.setItem('accessToken', response.data.accessToken);
      
      if (response.data.refreshToken) {
        localStorage.setItem('refreshToken', response.data.refreshToken);
      }
    }
    
    return response.data;
  } catch (error) {
    console.error('Registration API error:', error);
    throw error;
  }
};

/**
 * Logout the current user
 * @returns {Promise} - The response promise
 */
export const logout = async () => {
  // Get refresh token to invalidate on server
  const refreshToken = localStorage.getItem('refreshToken');
  
  // Clear tokens from localStorage
  localStorage.removeItem('accessToken');
  localStorage.removeItem('refreshToken');
  
  // Only call the API if we have a refresh token
  if (refreshToken) {
    try {
      await api.post('/auth/logout', { refreshToken });
    } catch (error) {
      console.error('Error during logout:', error);
      // Continue with client-side logout even if server request fails
    }
  }
  
  return { success: true };
};

/**
 * Request password reset
 * @param {string} email - User email
 * @returns {Promise} - The response promise
 */
export const requestPasswordReset = async (email) => {
  const response = await api.post('/auth/forgot-password', { email });
  return response.data;
};

/**
 * Reset password with token
 * @param {string} token - Password reset token
 * @param {string} password - New password
 * @returns {Promise} - The response promise
 */
export const resetPassword = async (token, password) => {
  const response = await api.post('/auth/reset-password', { token, password });
  return response.data;
};

/**
 * Verify email with token
 * @param {string} token - Email verification token
 * @returns {Promise} - The response promise
 */
export const verifyEmail = async (token) => {
  const response = await api.post('/auth/verify-email', { token });
  return response.data;
};

/**
 * Get current user profile
 * @returns {Promise} - The response promise
 */
export const getCurrentUser = async () => {
  const response = await api.get('/auth/me');
  return response.data;
};

/**
 * Update user profile
 * @param {Object} profileData - Updated profile data
 * @returns {Promise} - The response promise
 */
export const updateProfile = async (profileData) => {
  const response = await api.put('/auth/profile', profileData);
  return response.data;
};

/**
 * Change password
 * @param {string} currentPassword - Current password
 * @param {string} newPassword - New password
 * @returns {Promise} - The response promise
 */
export const changePassword = async (currentPassword, newPassword) => {
  const response = await api.post('/auth/change-password', {
    currentPassword,
    newPassword
  });
  return response.data;
};

/**
 * Refresh the authentication token
 * @returns {Promise} - The response promise
 */
export const refreshAuthToken = async () => {
  const refreshToken = localStorage.getItem('refreshToken');
  
  if (!refreshToken) {
    throw new Error('No refresh token available');
  }
  
  const response = await api.post('/auth/refresh', { refreshToken });
  
  if (response.data.accessToken) {
    localStorage.setItem('accessToken', response.data.accessToken);
    
    if (response.data.refreshToken) {
      localStorage.setItem('refreshToken', response.data.refreshToken);
    }
  }
  
  return response.data;
};

/**
 * Check if user is authenticated
 * @returns {boolean} - Whether the user is authenticated
 */
export const isAuthenticated = () => {
  const token = localStorage.getItem('accessToken');
  return !!token;
};

/**
 * Get the current authentication token
 * @returns {string|null} - The current token or null
 */
export const getToken = () => {
  return localStorage.getItem('accessToken');
};

export default {
  login,
  register,
  logout,
  requestPasswordReset,
  resetPassword,
  verifyEmail,
  getCurrentUser,
  updateProfile,
  changePassword,
  refreshAuthToken,
  isAuthenticated,
  getToken
};
